        if (names.isEmpty()) return render(emptyList())
        val accepted = names.filter { portions(it) > 0 }
        return render(accepted)
    }

    fun retry(attempts: Int): Int {
        if (attempts <= 0) return 0
        return 1 + retry(attempts - 1)
    }

