    fun classify(amount: Int): Int {
        var category = 0
        if (amount > 0) category++
        if (amount > 1) category++
        if (amount > 2) category++
        if (amount > 3) category++
        if (amount > 4) category++
        if (amount > 5) category++
        if (amount > 6) category++
        if (amount > 7) category++
        return category
    }

